+        <p class="eyebrow">Multi-select quiz</p>
+        <h1>Computer Languages</h1>
+        <p class="intro">Choose every answer that fits each question. Some questions have more than one correct choice.</p>
+      </header>
+
+      <div id="quiz-root"></div>
+    </div>
+  </main>
+
+  <script>
+    const quizQuestions = [
+      {
+        id: "compiled",
+        prompt: "Which of these languages are commonly compiled before they run?",
+        help: "Select all that apply. A language can still have multiple implementations, so focus on the most common use in production projects.",
