                <span class="choice-text">JavaScript</span>
              </label>
              <label class="choice" for="web-typescript">
                <input id="web-typescript" type="checkbox" name="web" value="TypeScript">
                <span class="choice-text">TypeScript</span>
              </label>
              <label class="choice" for="web-html">
                <input id="web-html" type="checkbox" name="web" value="HTML">
                <span class="choice-text">HTML</span>
              </label>
              <label class="choice" for="web-sql">
                <input id="web-sql" type="checkbox" name="web" value="SQL">
                <span class="choice-text">SQL</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="form-field">
          <fieldset>
            <legend>Which languages are popular for data analysis or scientific computing?</legend>
            <div class="choices">
              <label class="choice" for="data-python">
                <input id="data-python" type="checkbox" name="data" value="Python">
                <span class="choice-text">Python</span>
              </label>
              <label class="choice" for="data-r">
                <input id="data-r" type="checkbox" name="data" value="R">
                <span class="choice-text">R</span>
              </label>
              <label class="choice" for="data-fortran">
                <input id="data-fortran" type="checkbox" name="data" value="Fortran">
                <span class="choice-text">Fortran</span>
              </label>
              <label class="choice" for="data-css">
                <input id="data-css" type="checkbox" name="data" value="CSS">
                <span class="choice-text">CSS</span>
              </label>
            </div>
          </fieldset>
        </div>

        <div class="actions">
          <button type="submit">Submit answers</button>
          <p class="result" id="quiz-result" aria-live="polite"></p>
        </div>
      </form>
    </div>
  </main>

  <script>
    document.getElementById("language-quiz").addEventListener("submit", (event) => {
      event.preventDefault();

      const selectedCount = document.querySelectorAll("input[type='checkbox']:checked").length;
      const result = document.getElementById("quiz-result");
      const answerWord = selectedCount === 1 ? "answer" : "answers";

      result.textContent = `Saved ${selectedCount} selected ${answerWord}.`;
    });
  </script>
