       box-sizing: border-box;
     }

     body {
       min-height: 100vh;
       margin: 0;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       line-height: 1.5;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(139, 92, 246, 0.3), transparent 30rem),
         radial-gradient(circle at bottom right, rgba(34, 211, 238, 0.16), transparent 28rem),
         var(--bg);
     }

     .skip-link {
       position: absolute;
       top: 1rem;
       left: 1rem;
       z-index: 10;
       transform: translateY(-200%);
       padding: 0.75rem 1rem;
       color: #111827;
       background: var(--focus);
       border-radius: 999px;
       font-weight: 700;
     }

     .skip-link:focus {
       transform: translateY(0);
       outline: 3px solid #fff;
       outline-offset: 3px;
     }

     main {
       width: min(920px, calc(100% - 2rem));
       margin: 0 auto;
       padding: 4rem 0;
     }

     .quiz-shell {
       overflow: hidden;
       border: 1px solid rgba(255, 255, 255, 0.12);
       border-radius: 28px;
       background: rgba(20, 27, 47, 0.9);
       box-shadow: 0 24px 80px var(--shadow);
       backdrop-filter: blur(18px);
     }

     .hero {
       padding: clamp(2rem, 5vw, 4rem);
       background: linear-gradient(135deg, rgba(139, 92, 246, 0.28), rgba(20, 184, 166, 0.1));
       border-bottom: 1px solid var(--border);
     }

     .eyebrow {
       margin: 0 0 0.75rem;
       color: var(--accent-strong);
       font-size: 0.875rem;
       font-weight: 800;
       letter-spacing: 0.12em;
       text-transform: uppercase;
     }

     h1 {
       max-width: 13ch;
       margin: 0;
       font-size: clamp(2.3rem, 8vw, 5rem);
       line-height: 0.95;
       letter-spacing: -0.06em;
     }

     .intro {
       max-width: 58ch;
       margin: 1.25rem 0 0;
       color: var(--muted);
       font-size: 1.1rem;
     }

     form {
       display: grid;
       gap: 1.25rem;
       padding: clamp(1rem, 4vw, 2rem);
     }

     .form-field {
       border: 1px solid var(--border);
       border-radius: 22px;
       background: linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.015));
     }

     fieldset {
       min-width: 0;
       margin: 0;
       padding: clamp(1.25rem, 4vw, 2rem);
       border: 0;
     }

     legend {
       width: 100%;
       margin-bottom: 0.75rem;
       padding: 0;
       font-size: clamp(1.15rem, 3vw, 1.45rem);
       font-weight: 800;
       letter-spacing: -0.02em;
     }

     .help-text {
       margin: -0.25rem 0 1.25rem;
       color: var(--muted);
     }

     .choices {
       display: grid;
       grid-template-columns: repeat(2, minmax(0, 1fr));
       gap: 0.85rem;
     }

     .choice {
       display: flex;
       gap: 0.75rem;
       align-items: flex-start;
       min-height: 3.75rem;
       padding: 1rem;
       border: 1px solid var(--border);
       border-radius: 16px;
       background: rgba(11, 16, 32, 0.58);
       cursor: pointer;
       transition: transform 160ms ease, border-color 160ms ease, background-color 160ms ease;
     }

     .choice:hover {
       transform: translateY(-1px);
       border-color: var(--accent-strong);
       background: rgba(139, 92, 246, 0.13);
     }

     .choice input {
       width: 1.2rem;
       height: 1.2rem;
       flex: 0 0 auto;
       margin: 0.12rem 0 0;
       accent-color: var(--accent);
     }

     .choice input:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .choice-text {
       display: block;
       color: var(--text);
       font-weight: 700;
     }

     .actions {
       display: flex;
       flex-wrap: wrap;
       gap: 1rem;
       align-items: center;
       justify-content: space-between;
       padding-top: 0.5rem;
     }

     button {
       min-height: 3rem;
       padding: 0.85rem 1.35rem;
       border: 0;
       border-radius: 999px;
       color: #120a2a;
       background: linear-gradient(135deg, var(--accent-strong), #67e8f9);
       box-shadow: 0 14px 32px rgba(139, 92, 246, 0.35);
       font: inherit;
       font-weight: 900;
       cursor: pointer;
     }

     button:hover {
       filter: brightness(1.07);
     }

     button:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 4px;
     }

     .result {
       min-height: 1.5rem;
       margin: 0;
       color: var(--success);
       font-weight: 800;
     }

     @media (max-width: 640px) {
       main {
         width: min(100% - 1rem, 920px);
         padding: 0.5rem 0;
       }

       .quiz-shell {
         border-radius: 20px;
       }

       .choices {
         grid-template-columns: 1fr;
       }

       .actions {
         align-items: stretch;
         flex-direction: column;
       }
     }

     @media (prefers-reduced-motion: reduce) {
       *,
       *::before,
       *::after {
         scroll-behavior: auto !important;
         transition-duration: 0.01ms !important;
       }
     }

     @media (forced-colors: active) {
       .quiz-shell,
       .form-field,
       .choice {
         border: 1px solid CanvasText;
       }

       button {
         border: 2px solid ButtonText;
       }
     }
   </style>
 </head>
 <body>
   <a class="skip-link" href="#main-content">Skip to quiz</a>
   <main id="main-content">
     <div class="quiz-shell">
       <header class="hero">
         <p class="eyebrow">Multi-select quiz</p>
         <h1>Computer Languages</h1>
         <p class="intro">Choose every answer that fits each question. Some questions have more than one correct choice.</p>
       </header>

       <form id="language-quiz">
         <div class="form-field">
           <fieldset aria-describedby="compiled-help">
             <legend>Which of these languages are commonly compiled before they run?</legend>
             <p class="help-text" id="compiled-help">Select all that apply. A language can still have multiple implementations, so focus on the most common use in production projects.</p>
             <div class="choices">
               <label class="choice" for="compiled-c">
                 <input id="compiled-c" type="checkbox" name="compiled" value="C">
                 <span class="choice-text">C</span>
               </label>
               <label class="choice" for="compiled-go">
                 <input id="compiled-go" type="checkbox" name="compiled" value="Go">
                 <span class="choice-text">Go</span>
               </label>
               <label class="choice" for="compiled-ruby">
                 <input id="compiled-ruby" type="checkbox" name="compiled" value="Ruby">
                 <span class="choice-text">Ruby</span>
               </label>
               <label class="choice" for="compiled-rust">
                 <input id="compiled-rust" type="checkbox" name="compiled" value="Rust">
                 <span class="choice-text">Rust</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>Which languages are often used to build interactive web pages?</legend>
             <div class="choices">
               <label class="choice" for="web-javascript">
                 <input id="web-javascript" type="checkbox" name="web" value="JavaScript">
                 <span class="choice-text">JavaScript</span>
               </label>
               <label class="choice" for="web-typescript">
                 <input id="web-typescript" type="checkbox" name="web" value="TypeScript">
                 <span class="choice-text">TypeScript</span>
               </label>
               <label class="choice" for="web-html">
                 <input id="web-html" type="checkbox" name="web" value="HTML">
                 <span class="choice-text">HTML</span>
               </label>
               <label class="choice" for="web-sql">
                 <input id="web-sql" type="checkbox" name="web" value="SQL">
                 <span class="choice-text">SQL</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="form-field">
           <fieldset>
             <legend>Which languages are popular for data analysis or scientific computing?</legend>
             <div class="choices">
               <label class="choice" for="data-python">
                 <input id="data-python" type="checkbox" name="data" value="Python">
                 <span class="choice-text">Python</span>
               </label>
               <label class="choice" for="data-r">
                 <input id="data-r" type="checkbox" name="data" value="R">
                 <span class="choice-text">R</span>
               </label>
               <label class="choice" for="data-fortran">
                 <input id="data-fortran" type="checkbox" name="data" value="Fortran">
                 <span class="choice-text">Fortran</span>
               </label>
               <label class="choice" for="data-css">
                 <input id="data-css" type="checkbox" name="data" value="CSS">
                 <span class="choice-text">CSS</span>
               </label>
             </div>
           </fieldset>
         </div>

         <div class="actions">
           <button type="submit">Submit answers</button>
           <p class="result" id="quiz-result" aria-live="polite"></p>
         </div>
       </form>
     </div>
   </main>

   <script>
     document.getElementById("language-quiz").addEventListener("submit", (event) => {
       event.preventDefault();

       const selectedCount = document.querySelectorAll("input[type='checkbox']:checked").length;
       const result = document.getElementById("quiz-result");
       const answerWord = selectedCount === 1 ? "answer" : "answers";

       result.textContent = `Saved ${selectedCount} selected ${answerWord}.`;
     });
   </script>
 </body>
 </html>

')
